// src/components/KnowYourCandidate.js
import React, { useState } from 'react';

const KnowYourCandidate = ({ language }) => {
  const [constituency, setConstituency] = useState('');
  const [candidateInfo, setCandidateInfo] = useState(null);

  const handleSearch = () => {
    // Simulate candidate data based on constituency
    const candidates = {
      'delhi': {
        name: 'अरविंद केजरीवाल / Arvind Kejriwal',
        party: 'आम आदमी पार्टी / Aam Aadmi Party',
        education: 'आईआईटी खड़गपुर स्नातक / IIT Kharagpur Graduate',
        promises: [
          'शिक्षा और स्वास्थ्य में सुधार / Improve Education and Healthcare',
          'महिला सुरक्षा / Women Safety',
          'बुनियादी ढांचा विकास / Infrastructure Development'
        ]
      },
      'mumbai': {
        name: 'उद्धव ठाकरे / Uddhav Thackeray',
        party: 'शिव सेना / Shiv Sena',
        education: 'जेजे स्कूल ऑफ आर्ट्स / JJ School of Arts',
        promises: [
          'रोजगार सृजन / Job Creation',
          'पर्यावरण संरक्षण / Environmental Protection',
          'युवाओं के लिए कार्यक्रम / Programs for Youth'
        ]
      }
    };

    setCandidateInfo(candidates[constituency.toLowerCase()] || null);
  };

  const translations = {
    hindi: {
      title: "अपने उम्मीदवार को जानें",
      placeholder: "अपना निर्वाचन क्षेत्र दर्ज करें",
      search: "खोजें",
      candidateInfo: "उम्मीदवार की जानकारी",
      name: "नाम",
      party: "पार्टी",
      education: "शिक्षा",
      promises: "वादे",
      noInfo: "कृपया एक मान्य निर्वाचन क्षेत्र दर्ज करें"
    },
    english: {
      title: "Know Your Candidate",
      placeholder: "Enter your constituency",
      search: "Search",
      candidateInfo: "Candidate Information",
      name: "Name",
      party: "Party",
      education: "Education",
      promises: "Promises",
      noInfo: "Please enter a valid constituency"
    }
  };

  const t = translations[language];

  return (
    <div className="know-your-candidate">
      <h2>{t.title}</h2>
      
      <div className="search-section">
        <input
          type="text"
          value={constituency}
          onChange={(e) => setConstituency(e.target.value)}
          placeholder={t.placeholder}
          className="search-input"
        />
        <button onClick={handleSearch} className="search-button">
          {t.search}
        </button>
      </div>

      {candidateInfo ? (
        <div className="candidate-info">
          <h3>{t.candidateInfo}</h3>
          <div className="info-card">
            <p><strong>{t.name}:</strong> {candidateInfo.name}</p>
            <p><strong>{t.party}:</strong> {candidateInfo.party}</p>
            <p><strong>{t.education}:</strong> {candidateInfo.education}</p>
            <div className="promises">
              <strong>{t.promises}:</strong>
              <ul>
                {candidateInfo.promises.map((promise, index) => (
                  <li key={index}>{promise}</li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      ) : (
        constituency && <p className="no-info">{t.noInfo}</p>
      )}
    </div>
  );
};

export default KnowYourCandidate;
